/// structured metadata" as `Value::Null`; the SDK represents it as `None`, so
/// collapse `Null` to `None` and forward any real value as `Some(..)`.
fn metadata_from_details(details: Value) -> Option<Value> {
    if details.is_null() {
        None
    } else {
        Some(details)
    }
}

