        bus.emit(delta_event(sid, "b"));

        // An id never seen (or aged out) => empty replay, fall back to live only.
        let (replay, _rx) = bus.subscribe_with_replay(Some(Uuid::new_v4()));
        assert!(replay.is_empty());
