        let other = AgentSessionId::new_v4();

        bus.emit(delta_event(mine, "mine-1"));
        let anchor = {
            let h = bus.history.lock().unwrap();
            h.back().unwrap().id
        };
        bus.emit(delta_event(other, "other-secret"));
        bus.emit(delta_event(mine, "mine-2"));

